/**
 * The six Zones of an Instance, in display order. Each folder is numbered so it
 * sorts in a stable order in Obsidian's file explorer (ADR 0003).
 */
export const ZONES = Object.freeze({
  sources: '10-sources',
  human: '20-human',
  proposals: '30-proposals',
  compiled: '40-compiled',
  ops: '50-ops',
  system: '90-system',
});

/** Zone folder names in order. */
export const ZONE_FOLDERS = Object.freeze(Object.values(ZONES));

/** First line of every generated file (`sbk index` output); such a file is never hand-written. */
export const GENERATED_MARKER = '<!-- generated by sbk index; do not edit -->';

/** Path of the framework lock record, relative to the vault root. */
export const LOCK_PATH = `${ZONES.system}/framework.lock`;

/** Where `import` keeps verbatim what fits no Zone, one folder per adapter (ADR 0011). Links inside it are not checked. */
export const IMPORTED_AREA = `${ZONES.human}/_imported`;

/** Where `import` records what it did: the manifest (ADR 0011). */
export const MIGRATION_DIR = `${ZONES.ops}/migration`;

/** Vault-relative path of the import manifest. */
export const MANIFEST_PATH = `${MIGRATION_DIR}/manifest.json`;

/** Vault-relative path of the operational memory note. */
export const HOT_PATH = `${ZONES.ops}/hot.md`;

/** Quarantine folder: material that matched a secret pattern. The CLI never deletes from it. */
export const QUARANTINE_DIR = `${ZONES.ops}/quarantine`;

/**
 * True for a path that is held-back raw material, never knowledge: a check that judges notes
 * (schema, links, orphans, coverage, review dates) skips it. The one place that lists such paths.
 * @param {string} path vault-relative path with forward slashes
 * @returns {boolean}
 */
export function isHeldBack(path) {
  return path.startsWith(`${QUARANTINE_DIR}/`);
}

/** Name of the generated index note in each indexed Zone folder. */
export const ZONE_INDEX_NAME = '_index.md';

/** Zones that get an `_index.md`. The System zone is managed by `upgrade`, so it gets none. */
export const INDEXED_ZONES = Object.freeze([ZONES.sources, ZONES.human, ZONES.proposals, ZONES.compiled, ZONES.ops]);

/**
 * True for the generated index note of a Zone. Checks that judge curated notes
 * (orphans, pending proposals) skip these: they list every item, so counting
 * their links or treating them as proposals would hide or invent findings.
 * @param {string} path vault-relative path with forward slashes
 * @returns {boolean}
 */
export function isZoneIndex(path) {
  return INDEXED_ZONES.some((zone) => path === `${zone}/${ZONE_INDEX_NAME}`);
}
